import React, { useState, useEffect } from 'react'
import CommonSection from '../share/CommonSection'
import { Col, Container, Row } from 'reactstrap'
import "../style/tour.css"
import tourData from '../assets/data/tours'
import TourCard from '../share/TourCard'
import SearchBar from '../share/SearchBar'
import Newsletter from '../share/Newsletter'

import useFetch from '../hooks/useFetch'
import { BASE_URL } from '../utils/config'

const Tour = () => {

  const [pageCount, setPageCount] = useState(0)
  const [page, setPage] = useState(0)
  
  const {data:tours, loading, error} = useFetch(`${BASE_URL}/tours`)
  const {data:tourCount} = useFetch(`${BASE_URL}/tours/search/getTourCount`)

  useEffect(() => {
    const pages = Math.ceil(5 / 4)
    setPageCount(pages)
  }, [page, tourCount])

  return (
    <>
      <CommonSection title={"Tất cả các tour"} />
      <section>
        <Container>
          <Row>
            <SearchBar />
          </Row>
        </Container>
      </section>
      <section className='pt-0'>
        <Container>
          {
            !loading && !err
          }
        </Container>
      </section>
      <Newsletter/>
    </>
  )
}

export default Tour
